-- ============================================================================
-- BASELINE: production schema as dumped on 2026-09-03 (#721 / T111 / T127)
-- ============================================================================
-- `supabase db dump --linked` of project mhijaqahbceuahfzezbh, wrapped by three
-- hand-added sections for what pg_dump cannot express: ROLES at the top,
-- POST-DUMP ALIGNMENT (95 revokes of default privileges) and CRON SCHEDULES at
-- the bottom. Each section says where its content came from. Verified by
-- `supabase db diff --linked --schema public` against a shadow database built
-- from this file alone: see the decision doc for the result.
--
-- Why this exists: production's migration record held 252 versions but the repo
-- held 95 files. The other 158 were applied through the dashboard or MCP between
-- March and July 2026 and never got a file, so a fresh apply of the repo could not
-- reproduce production. This file is the repo's new migration zero: everything
-- production ran up to this date, in one place. Migrations after it are the
-- forward record as usual.
--
-- The 94 pre-baseline files now live in supabase/migrations-archive/ with a JSON
-- export of the full 252-row production ledger (version, name, statements), so
-- no SQL is lost. Decision doc: docs/decisions/2026-09-03-t111-schema-baseline.md
--
-- Not carried (outside pg_dump's scope, not schema, or not SBD's to rebuild):
--   auth config and hooks, storage.buckets rows (the only remaining bucket is
--   another property's), vault secrets, edge function deployments.
--
-- Do not edit this file. A change to production is a new migration after it.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- ROLES (cluster-level, so `db dump` omits them; taken from `db dump --role-only`)
-- sbdops_readonly is a read-only LOGIN role that exists in production with no
-- migration behind it: not in any repo file, not in any of the 252 recorded
-- statements. It receives 10 grants further down this file, so a rebuild needs
-- it to exist. Guarded so re-running never errors. No password is carried; a
-- rebuilt environment sets its own.
-- The three statement_timeout settings are production role config with no
-- migration behind them either (anon 3s, authenticated/authenticator 8s).
-- ----------------------------------------------------------------------------
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'sbdops_readonly') then
    create role "sbdops_readonly";
  end if;
end $$;
ALTER ROLE "sbdops_readonly" WITH INHERIT NOCREATEROLE NOCREATEDB LOGIN NOBYPASSRLS;
ALTER ROLE "anon" SET "statement_timeout" TO '3s';
ALTER ROLE "authenticated" SET "statement_timeout" TO '8s';
ALTER ROLE "authenticator" SET "statement_timeout" TO '8s';




SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE EXTENSION IF NOT EXISTS "pg_cron" WITH SCHEMA "pg_catalog";






CREATE EXTENSION IF NOT EXISTS "pg_net" WITH SCHEMA "extensions";






COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE EXTENSION IF NOT EXISTS "http" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "vector" WITH SCHEMA "public";






