CREATE OR REPLACE FUNCTION "public"."aip_admin_get_candidates"("p_facility_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN (SELECT jsonb_agg(jsonb_build_object(
    'id',c.id,'name',c.first_name||' '||c.last_name,'email',c.email,
    'facility',f.name,'facility_id',c.facility_id,
    'knowledge_level',(SELECT code FROM aip_levels WHERE id=c.knowledge_level_id),
    'script_level',(SELECT code FROM aip_levels WHERE id=c.script_level_id),
    'practice_level',(SELECT code FROM aip_levels WHERE id=c.practice_level_id),
    'overall_belt',(SELECT code FROM aip_levels WHERE id=c.overall_belt_id),
    'pending_requests',(SELECT COUNT(*) FROM aip_assessment_requests r WHERE r.candidate_id=c.id AND r.status='pending'),
    'completed_tests',(SELECT COUNT(*) FROM aip_proctored_sessions ps WHERE ps.candidate_id=c.id AND ps.completed_at IS NOT NULL)
  ) ORDER BY f.name, c.last_name)
  FROM aip_candidates c JOIN aip_facilities f ON f.id=c.facility_id
  WHERE c.is_active AND (p_facility_id IS NULL OR c.facility_id=p_facility_id));
END; $$;


ALTER FUNCTION "public"."aip_admin_get_candidates"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_admin_get_facilities"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN (SELECT jsonb_agg(jsonb_build_object(
    'id',f.id,'name',f.name,'code',f.facility_code,'location',f.location,
    'candidate_count',(SELECT COUNT(*) FROM aip_candidates c WHERE c.facility_id=f.id AND c.is_active),
    'assessor_count',(SELECT COUNT(*) FROM aip_assessors a WHERE a.facility_id=f.id AND a.is_active),
    'active_tests',(SELECT COUNT(*) FROM aip_proctored_sessions ps WHERE ps.facility_id=f.id AND ps.completed_at IS NULL)
  ) ORDER BY f.name) FROM aip_facilities f WHERE f.is_active);
END; $$;


ALTER FUNCTION "public"."aip_admin_get_facilities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_admin_login"("p_email" "text", "p_password" "text", "p_pin" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v aip_admin_users%ROWTYPE;
BEGIN
  SELECT * INTO v FROM aip_admin_users WHERE email=lower(p_email) AND is_active;
  IF v.id IS NULL THEN RETURN jsonb_build_object('error','Invalid credentials'); END IF;
  IF v.password_hash!=p_password THEN RETURN jsonb_build_object('error','Invalid credentials'); END IF;
  IF v.pin!=p_pin THEN RETURN jsonb_build_object('error','Invalid PIN'); END IF;
  UPDATE aip_admin_users SET last_login_at=now() WHERE id=v.id;
  RETURN jsonb_build_object('success',true,'admin_id',v.id,'email',v.email,'name',v.display_name,'role',v.role,
    'facility_id',v.facility_id);
END; $$;


ALTER FUNCTION "public"."aip_admin_login"("p_email" "text", "p_password" "text", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_approve_assessment"("p_admin_id" "uuid", "p_request_id" "uuid", "p_assessment_type" "text" DEFAULT 'level_1_knowledge'::"text", "p_question_count" integer DEFAULT 50, "p_time_limit" integer DEFAULT 60, "p_available_days" integer DEFAULT 14) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_req aip_assessment_requests%ROWTYPE; v_fa_id UUID;
BEGIN
  SELECT * INTO v_req FROM aip_assessment_requests WHERE id = p_request_id AND status = 'pending';
  IF v_req.id IS NULL THEN RETURN jsonb_build_object('error','Request not found or already processed'); END IF;
  -- Update request
  UPDATE aip_assessment_requests SET status = 'approved', reviewed_by = p_admin_id, reviewed_at = now(),
    expires_at = now() + (p_available_days || ' days')::interval WHERE id = p_request_id;
  -- Create formal assessment
  INSERT INTO aip_formal_assessments (request_id, candidate_id, level_id, assessment_type,
    question_count, time_limit_minutes, created_by, available_until)
  VALUES (p_request_id, v_req.candidate_id, v_req.level_id, p_assessment_type,
    p_question_count, p_time_limit, p_admin_id, now() + (p_available_days || ' days')::interval)
  RETURNING id INTO v_fa_id;
  RETURN jsonb_build_object('success', true, 'formal_assessment_id', v_fa_id);
END;
$$;


ALTER FUNCTION "public"."aip_approve_assessment"("p_admin_id" "uuid", "p_request_id" "uuid", "p_assessment_type" "text", "p_question_count" integer, "p_time_limit" integer, "p_available_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_approve_registration"("p_registration_id" "uuid", "p_admin_id" "uuid", "p_knowledge_level" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_reg aip_registrations%ROWTYPE; v_fac aip_facilities%ROWTYPE; v_count INTEGER;
BEGIN
  SELECT * INTO v_reg FROM aip_registrations WHERE id = p_registration_id AND status = 'pending';
  IF v_reg.id IS NULL THEN RETURN jsonb_build_object('error','Registration not found'); END IF;
  SELECT * INTO v_fac FROM aip_facilities WHERE id = v_reg.facility_id;
  SELECT COUNT(*) INTO v_count FROM aip_candidates WHERE facility_id = v_reg.facility_id AND is_active;
  IF v_count >= v_fac.max_candidates THEN
    RETURN jsonb_build_object('error','Seat limit reached ('||v_fac.max_candidates||' candidates). Request a seat increase from SIPS admin.');
  END IF;
  INSERT INTO aip_candidates (email, pin, first_name, last_name, facility_id, knowledge_level_id, script_level_id, practice_level_id, overall_belt_id, assigned_by)
  VALUES (v_reg.email, v_reg.pin, v_reg.first_name, v_reg.last_name, v_reg.facility_id,
    COALESCE(p_knowledge_level, 'a0000001-0000-0000-0000-000000000001'),
    'a0000001-0000-0000-0000-000000000001',
    COALESCE(p_knowledge_level, 'a0000001-0000-0000-0000-000000000001'),
    COALESCE(p_knowledge_level, 'a0000001-0000-0000-0000-000000000001'),
    p_admin_id);
  UPDATE aip_registrations SET status = 'approved', reviewed_by = p_admin_id, reviewed_at = now() WHERE id = p_registration_id;
  RETURN jsonb_build_object('success',true);
END; $$;


ALTER FUNCTION "public"."aip_approve_registration"("p_registration_id" "uuid", "p_admin_id" "uuid", "p_knowledge_level" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_candidate_login"("p_email" "text", "p_pin" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v aip_candidates%ROWTYPE; f aip_facilities%ROWTYPE;
BEGIN
  SELECT * INTO v FROM aip_candidates WHERE email=lower(p_email) AND pin=p_pin AND is_active;
  IF v.id IS NULL THEN RETURN jsonb_build_object('error','Invalid email or PIN'); END IF;
  SELECT * INTO f FROM aip_facilities WHERE id=v.facility_id;
  RETURN jsonb_build_object('success',true,'candidate_id',v.id,
    'name',v.first_name||' '||v.last_name,'email',v.email,
    'facility_id',v.facility_id,'facility_name',f.name,
    'knowledge_level_id',v.knowledge_level_id,
    'knowledge_level',(SELECT name FROM aip_levels WHERE id=v.knowledge_level_id),
    'script_level_id',v.script_level_id,
    'script_level',(SELECT name FROM aip_levels WHERE id=v.script_level_id),
    'practice_level_id',v.practice_level_id,
    'practice_level',(SELECT name FROM aip_levels WHERE id=v.practice_level_id),
    'overall_belt_id',v.overall_belt_id,
    'overall_belt',(SELECT name FROM aip_levels WHERE id=v.overall_belt_id),
    'available_assessments',(
      SELECT jsonb_agg(jsonb_build_object('id',fa.id,'level',l.name,'type',fa.assessment_type,
        'questions',fa.question_count,'time_limit',fa.time_limit_minutes,'threshold',fa.passing_threshold))
      FROM aip_formal_assessments fa JOIN aip_levels l ON l.id=fa.level_id
      WHERE fa.candidate_id=v.id AND fa.status='available'
        AND (fa.available_from IS NULL OR fa.available_from<=now())
        AND (fa.available_until IS NULL OR fa.available_until>=now())
    ));
END; $$;


ALTER FUNCTION "public"."aip_candidate_login"("p_email" "text", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_candidate_register"("p_email" "text", "p_first_name" "text", "p_last_name" "text", "p_facility_code" "text", "p_pin" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_fac aip_facilities%ROWTYPE; v_exists BOOLEAN;
BEGIN
  SELECT * INTO v_fac FROM aip_facilities WHERE facility_code = upper(p_facility_code) AND is_active;
  IF v_fac.id IS NULL THEN RETURN jsonb_build_object('error','Facility code not found. Contact your administrator.'); END IF;
  SELECT EXISTS(SELECT 1 FROM aip_candidates WHERE email = lower(p_email)) INTO v_exists;
  IF v_exists THEN RETURN jsonb_build_object('error','Email already registered.'); END IF;
  SELECT EXISTS(SELECT 1 FROM aip_registrations WHERE email = lower(p_email) AND status = 'pending') INTO v_exists;
  IF v_exists THEN RETURN jsonb_build_object('error','Registration already pending.'); END IF;
  INSERT INTO aip_registrations (email, first_name, last_name, facility_id, pin)
  VALUES (lower(p_email), p_first_name, p_last_name, v_fac.id, p_pin);
  RETURN jsonb_build_object('success',true,'message','Registration submitted. Your facility administrator will review your request.');
END; $$;


ALTER FUNCTION "public"."aip_candidate_register"("p_email" "text", "p_first_name" "text", "p_last_name" "text", "p_facility_code" "text", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_complete_proctored_session"("p_session_id" "uuid", "p_responses" "jsonb", "p_proctor_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_session aip_proctored_sessions%ROWTYPE;
  v_results JSONB;
BEGIN
  SELECT * INTO v_session FROM aip_proctored_sessions WHERE id = p_session_id;
  IF v_session.id IS NULL THEN RETURN jsonb_build_object('error','Session not found'); END IF;
  -- Submit the quiz
  v_results := aip_submit_quiz(v_session.attempt_id, p_responses,
    (SELECT email FROM aip_candidates WHERE id = v_session.candidate_id));
  -- Update session
  UPDATE aip_proctored_sessions SET
    completed_at = now(),
    total_questions = (v_results->>'total_questions')::INTEGER,
    proctor_notes = p_proctor_notes
  WHERE id = p_session_id;
  -- Mark formal assessment as completed
  UPDATE aip_formal_assessments SET status = 'completed' WHERE id = v_session.formal_assessment_id;
  RETURN jsonb_build_object('success', true, 'session_id', p_session_id, 'results', v_results);
END;
$$;


ALTER FUNCTION "public"."aip_complete_proctored_session"("p_session_id" "uuid", "p_responses" "jsonb", "p_proctor_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_create_candidate"("p_admin_id" "uuid", "p_email" "text", "p_pin" "text", "p_first_name" "text", "p_last_name" "text", "p_facility_id" "uuid", "p_overall_belt_id" "uuid", "p_knowledge_level_id" "uuid" DEFAULT NULL::"uuid", "p_script_level_id" "uuid" DEFAULT NULL::"uuid", "p_practice_level_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_id UUID;
BEGIN
  INSERT INTO aip_candidates (email, pin, first_name, last_name, facility_id,
    overall_belt_id, knowledge_level_id, script_level_id, practice_level_id,
    assigned_by, notes)
  VALUES (lower(p_email), p_pin, p_first_name, p_last_name, p_facility_id,
    p_overall_belt_id,
    COALESCE(p_knowledge_level_id, p_overall_belt_id),
    COALESCE(p_script_level_id, p_overall_belt_id),
    COALESCE(p_practice_level_id, p_overall_belt_id),
    p_admin_id, p_notes)
  RETURNING id INTO v_id;
  -- Log initial level assignment
  INSERT INTO aip_candidate_level_history (candidate_id, dimension, to_level_id, reason, changed_by)
  VALUES (v_id, 'overall_belt', p_overall_belt_id, 'placement', p_admin_id);
  RETURN jsonb_build_object('success', true, 'candidate_id', v_id);
END;
$$;


ALTER FUNCTION "public"."aip_create_candidate"("p_admin_id" "uuid", "p_email" "text", "p_pin" "text", "p_first_name" "text", "p_last_name" "text", "p_facility_id" "uuid", "p_overall_belt_id" "uuid", "p_knowledge_level_id" "uuid", "p_script_level_id" "uuid", "p_practice_level_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_generate_quiz"("p_level_id" "uuid", "p_mode" "text" DEFAULT 'practice_quiz'::"text", "p_count" integer DEFAULT 25, "p_categories" "text"[] DEFAULT NULL::"text"[], "p_difficulty_override" "jsonb" DEFAULT NULL::"jsonb", "p_parts" "text"[] DEFAULT NULL::"text"[], "p_exclude_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_easy_pct NUMERIC;
  v_med_pct NUMERIC;
  v_hard_pct NUMERIC;
  v_easy_count INTEGER;
  v_med_count INTEGER;
  v_hard_count INTEGER;
  v_passing INTEGER;
  v_level_code TEXT;
  v_attempt_id UUID;
  v_questions JSONB;
BEGIN
  -- Get level info
  SELECT code, passing_threshold INTO v_level_code, v_passing
  FROM aip_levels WHERE id = p_level_id;

  IF v_level_code IS NULL THEN
    RETURN jsonb_build_object('error', 'Level not found');
  END IF;

  -- Determine difficulty distribution
  IF p_difficulty_override IS NOT NULL THEN
    v_easy_pct := (p_difficulty_override->>'easy')::NUMERIC / 100;
    v_med_pct := (p_difficulty_override->>'medium')::NUMERIC / 100;
    v_hard_pct := (p_difficulty_override->>'hard')::NUMERIC / 100;
  ELSIF p_mode = 'timed_test' THEN
    IF v_level_code = 'BkB' THEN
      v_easy_pct := 0.10; v_med_pct := 0.40; v_hard_pct := 0.50;
    ELSE
      v_easy_pct := 0.20; v_med_pct := 0.50; v_hard_pct := 0.30;
    END IF;
  ELSE
    v_easy_pct := 0.40; v_med_pct := 0.40; v_hard_pct := 0.20;
  END IF;

  v_easy_count := CEIL(p_count * v_easy_pct);
  v_hard_count := CEIL(p_count * v_hard_pct);
  v_med_count := p_count - v_easy_count - v_hard_count;
  IF v_med_count < 0 THEN v_med_count := 0; END IF;

  -- Create attempt record
  INSERT INTO aip_assessment_attempts (level_id, mode, total_questions, config)
  VALUES (
    p_level_id,
    p_mode::aip_assessment_mode,
    p_count,
    jsonb_build_object(
      'difficulty_distribution', jsonb_build_object('easy', v_easy_count, 'medium', v_med_count, 'hard', v_hard_count),
      'categories', p_categories,
      'parts', p_parts
    )
  )
  RETURNING id INTO v_attempt_id;

  -- Select questions with difficulty distribution
  WITH easy_qs AS (
    SELECT id, question_number, question_text, question_type::TEXT, content_category::TEXT, difficulty::TEXT, part::TEXT, tags
    FROM aip_questions
    WHERE level_id = p_level_id
      AND is_active = true AND is_approved = true
      AND difficulty = 'easy'
      AND (p_categories IS NULL OR content_category::TEXT = ANY(p_categories))
      AND (p_parts IS NULL OR part::TEXT = ANY(p_parts))
      AND (p_exclude_ids IS NULL OR id != ALL(p_exclude_ids))
    ORDER BY random()
    LIMIT v_easy_count
  ),
  medium_qs AS (
    SELECT id, question_number, question_text, question_type::TEXT, content_category::TEXT, difficulty::TEXT, part::TEXT, tags
    FROM aip_questions
    WHERE level_id = p_level_id
      AND is_active = true AND is_approved = true
      AND difficulty = 'medium'
      AND (p_categories IS NULL OR content_category::TEXT = ANY(p_categories))
      AND (p_parts IS NULL OR part::TEXT = ANY(p_parts))
      AND (p_exclude_ids IS NULL OR id != ALL(p_exclude_ids))
    ORDER BY random()
    LIMIT v_med_count
  ),
  hard_qs AS (
    SELECT id, question_number, question_text, question_type::TEXT, content_category::TEXT, difficulty::TEXT, part::TEXT, tags
    FROM aip_questions
    WHERE level_id = p_level_id
      AND is_active = true AND is_approved = true
      AND difficulty = 'hard'
      AND (p_categories IS NULL OR content_category::TEXT = ANY(p_categories))
      AND (p_parts IS NULL OR part::TEXT = ANY(p_parts))
      AND (p_exclude_ids IS NULL OR id != ALL(p_exclude_ids))
    ORDER BY random()
    LIMIT v_hard_count
  ),
  all_qs AS (
    SELECT * FROM easy_qs
    UNION ALL SELECT * FROM medium_qs
    UNION ALL SELECT * FROM hard_qs
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', q.id,
      'question_number', q.question_number,
      'question_text', q.question_text,
      'question_type', q.question_type,
      'content_category', q.content_category,
      'difficulty', q.difficulty,
      'part', q.part,
      'tags', q.tags
    ) ORDER BY random()
  )
  INTO v_questions
  FROM all_qs q;

  -- Return quiz package (NO answers included)
  RETURN jsonb_build_object(
    'attempt_id', v_attempt_id,
    'level_code', v_level_code,
    'mode', p_mode,
    'passing_threshold', v_passing,
    'total_questions', COALESCE(jsonb_array_length(v_questions), 0),
    'questions', COALESCE(v_questions, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."aip_generate_quiz"("p_level_id" "uuid", "p_mode" "text", "p_count" integer, "p_categories" "text"[], "p_difficulty_override" "jsonb", "p_parts" "text"[], "p_exclude_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_generate_weak_spot_quiz"("p_candidate_email" "text", "p_level_id" "uuid" DEFAULT NULL::"uuid", "p_count" integer DEFAULT 15) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_weak_cats TEXT[];
  v_attempt_id UUID;
  v_questions JSONB;
BEGIN
  -- Find categories below 80%
  SELECT array_agg(category) INTO v_weak_cats
  FROM (
    SELECT q.content_category::TEXT as category,
      ROUND(COUNT(*) FILTER (WHERE qr.is_correct = true)::NUMERIC / NULLIF(COUNT(*),0) * 100, 1) as acc
    FROM aip_question_responses qr
    JOIN aip_assessment_attempts a ON a.id = qr.attempt_id
    JOIN aip_questions q ON q.id = qr.question_id
    WHERE a.candidate_email = p_candidate_email
      AND (p_level_id IS NULL OR a.level_id = p_level_id)
      AND qr.is_correct IS NOT NULL
    GROUP BY q.content_category HAVING COUNT(*) >= 3
  ) sub WHERE acc < 80;

  -- If no weak areas, use hard questions
  IF v_weak_cats IS NULL OR array_length(v_weak_cats, 1) IS NULL THEN
    v_weak_cats := NULL;
  END IF;

  -- Create attempt
  INSERT INTO aip_assessment_attempts (level_id, mode, total_questions, candidate_email,
    config)
  VALUES (p_level_id, 'weak_spot', p_count, p_candidate_email,
    jsonb_build_object('weak_categories', v_weak_cats))
  RETURNING id INTO v_attempt_id;

  -- Select questions from weak categories (or hard if none)
  SELECT jsonb_agg(jsonb_build_object(
    'id', id, 'question_number', question_number, 'question_text', question_text,
    'question_type', question_type::TEXT, 'content_category', content_category::TEXT,
    'difficulty', difficulty::TEXT, 'part', part::TEXT, 'tags', tags
  ) ORDER BY random())
  INTO v_questions
  FROM aip_questions
  WHERE is_active AND is_approved
    AND (p_level_id IS NULL OR level_id = p_level_id)
    AND (v_weak_cats IS NULL OR content_category::TEXT = ANY(v_weak_cats))
    AND (v_weak_cats IS NOT NULL OR difficulty = 'hard')
  LIMIT p_count;

  RETURN jsonb_build_object(
    'attempt_id', v_attempt_id, 'mode', 'weak_spot',
    'weak_categories', v_weak_cats,
    'total_questions', COALESCE(jsonb_array_length(v_questions), 0),
    'questions', COALESCE(v_questions, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."aip_generate_weak_spot_quiz"("p_candidate_email" "text", "p_level_id" "uuid", "p_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_get_admin_dashboard"("p_admin_id" "uuid", "p_facility_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_role TEXT; v_fid UUID;
BEGIN
  SELECT role, facility_id INTO v_role, v_fid FROM aip_admin_users WHERE id = p_admin_id;
  -- Facility admins only see their facility
  IF v_role != 'sips_admin' AND p_facility_id IS NULL THEN p_facility_id := v_fid; END IF;

  RETURN jsonb_build_object(
    'facilities', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', f.id, 'name', f.name, 'code', f.facility_code, 'location', f.location,
        'candidate_count', (SELECT COUNT(*) FROM aip_candidates WHERE facility_id = f.id AND is_active),
        'assessor_count', (SELECT COUNT(*) FROM aip_assessors WHERE facility_id = f.id AND is_active)
      )), '[]'::jsonb)
      FROM aip_facilities f WHERE f.is_active
      AND (p_facility_id IS NULL OR f.id = p_facility_id)
    ),
    'candidates', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', c.id, 'name', c.display_name, 'email', c.email,
        'facility', f.name, 'facility_code', f.facility_code,
        'overall_belt', l.name, 'belt_code', l.code,
        'knowledge_level', kl.code, 'script_level', sl.code
      ) ORDER BY f.name, c.last_name), '[]'::jsonb)
      FROM aip_candidates c
      JOIN aip_facilities f ON f.id = c.facility_id
      LEFT JOIN aip_levels l ON l.id = c.overall_belt_id
      LEFT JOIN aip_levels kl ON kl.id = c.knowledge_level_id
      LEFT JOIN aip_levels sl ON sl.id = c.script_level_id
      WHERE c.is_active AND (p_facility_id IS NULL OR c.facility_id = p_facility_id)
    ),
    'pending_requests', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', ar.id, 'candidate_name', c.display_name,
        'facility', f.facility_code, 'level', l.name,
        'type', ar.request_type, 'requested_at', ar.requested_at
      ) ORDER BY ar.requested_at), '[]'::jsonb)
      FROM aip_assessment_requests ar
      JOIN aip_candidates c ON c.id = ar.candidate_id
      JOIN aip_facilities f ON f.id = c.facility_id
      JOIN aip_levels l ON l.id = ar.level_id
      WHERE ar.status = 'pending'
      AND (p_facility_id IS NULL OR c.facility_id = p_facility_id)
    ),
    'recent_sessions', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'candidate', c.display_name, 'facility', f.facility_code,
        'level', l.name, 'score', ps.score_percentage,
        'passed', ps.passed, 'date', ps.completed_at,
        'assessor', a.display_name
      ) ORDER BY ps.completed_at DESC), '[]'::jsonb)
      FROM aip_proctored_sessions ps
      JOIN aip_candidates c ON c.id = ps.candidate_id
      JOIN aip_facilities f ON f.id = ps.facility_id
      JOIN aip_formal_assessments fa ON fa.id = ps.formal_assessment_id
      JOIN aip_levels l ON l.id = fa.level_id
      LEFT JOIN aip_assessors a ON a.id = ps.assessor_id
      WHERE ps.completed_at IS NOT NULL
      AND (p_facility_id IS NULL OR ps.facility_id = p_facility_id)
      LIMIT 20
    ),
    'content_stats', (SELECT aip_get_admin_stats())
  );
END;
$$;


ALTER FUNCTION "public"."aip_get_admin_dashboard"("p_admin_id" "uuid", "p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_get_admin_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN jsonb_build_object(
    'questions', (SELECT COUNT(*) FROM aip_questions),
    'answers', (SELECT COUNT(*) FROM aip_answers),
    'scripts', (SELECT COUNT(*) FROM aip_scripts),
    'levels', (SELECT COUNT(*) FROM aip_levels),
    'questions_with_answers', (
      SELECT COUNT(DISTINCT q.id) 
      FROM aip_questions q 
      JOIN aip_answers a ON a.question_id = q.id
    ),
    'by_level', (
      SELECT jsonb_agg(jsonb_build_object(
        'code', l.code,
        'name', l.name,
        'questions', sub.q_count,
        'answers', sub.a_count,
        'knowledge', sub.k_count,
        'scenarios', sub.s_count
      ) ORDER BY l.sort_order)
      FROM (
        SELECT q.level_id,
          COUNT(*) as q_count,
          COUNT(*) FILTER (WHERE q.part = 'knowledge') as k_count,
          COUNT(*) FILTER (WHERE q.part = 'scenario') as s_count,
          (SELECT COUNT(*) FROM aip_answers a WHERE a.question_id IN (
            SELECT id FROM aip_questions WHERE level_id = q.level_id
          )) as a_count
        FROM aip_questions q
        GROUP BY q.level_id
      ) sub
      JOIN aip_levels l ON l.id = sub.level_id
    )
  );
END;
$$;


ALTER FUNCTION "public"."aip_get_admin_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_get_candidate_analytics"("p_candidate_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'total_attempts', COUNT(*),
    'total_questions_answered', SUM(total_questions),
    'average_score', ROUND(AVG(score_percentage), 1),
    'attempts_by_level', (
      SELECT jsonb_agg(jsonb_build_object(
        'level_code', l.code,
        'level_name', l.name,
        'attempts', sub.cnt,
        'avg_score', sub.avg_score,
        'best_score', sub.best_score,
        'last_attempt', sub.last_attempt
      ) ORDER BY l.sort_order)
      FROM (
        SELECT level_id, COUNT(*) cnt, ROUND(AVG(score_percentage),1) avg_score,
               MAX(score_percentage) best_score, MAX(completed_at) last_attempt
        FROM aip_assessment_attempts
        WHERE candidate_email = p_candidate_email AND completed_at IS NOT NULL
        GROUP BY level_id
      ) sub
      JOIN aip_levels l ON l.id = sub.level_id
    ),
    'flashcard_stats', (
      SELECT jsonb_build_object(
        'total_cards', COUNT(*),
        'mastered', COUNT(*) FILTER (WHERE status = 'mastered'),
        'learning', COUNT(*) FILTER (WHERE status = 'learning'),
        'new', COUNT(*) FILTER (WHERE status = 'new'),
        'mastery_rate', CASE WHEN COUNT(*) > 0 
          THEN ROUND(COUNT(*) FILTER (WHERE status = 'mastered')::NUMERIC / COUNT(*) * 100, 1)
          ELSE 0 END
      )
      FROM aip_flashcard_progress
      WHERE candidate_email = p_candidate_email
    ),
    'recent_attempts', (
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id,
        'level_code', l.code,
        'mode', a.mode::TEXT,
        'score', a.score_percentage,
        'passed', a.passed,
        'completed_at', a.completed_at,
        'total_questions', a.total_questions
      ) ORDER BY a.completed_at DESC)
      FROM (
        SELECT * FROM aip_assessment_attempts
        WHERE candidate_email = p_candidate_email AND completed_at IS NOT NULL
        ORDER BY completed_at DESC LIMIT 10
      ) a
      JOIN aip_levels l ON l.id = a.level_id
    )
  )
  INTO v_result
  FROM aip_assessment_attempts
  WHERE candidate_email = p_candidate_email;

  RETURN COALESCE(v_result, jsonb_build_object(
    'total_attempts', 0,
    'total_questions_answered', 0,
    'average_score', 0,
    'attempts_by_level', '[]'::jsonb,
    'flashcard_stats', jsonb_build_object('total_cards', 0, 'mastered', 0, 'learning', 0, 'new', 0, 'mastery_rate', 0),
    'recent_attempts', '[]'::jsonb
  ));
END;
$$;


ALTER FUNCTION "public"."aip_get_candidate_analytics"("p_candidate_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_get_candidate_profile"("p_candidate_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_build_object(
      'candidate', jsonb_build_object(
        'id', c.id, 'name', c.display_name, 'email', c.email,
        'facility', f.name,
        'knowledge_level', kl.name, 'knowledge_code', kl.code,
        'script_level', sl.name, 'script_code', sl.code,
        'practice_level', pl.name, 'practice_code', pl.code,
        'overall_belt', ob.name, 'overall_belt_code', ob.code
      ),
      'available_assessments', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
          'id', fa.id, 'level', l.name, 'level_code', l.code,
          'type', fa.assessment_type, 'questions', fa.question_count,
          'time_limit', fa.time_limit_minutes, 'threshold', fa.passing_threshold,
          'available_until', fa.available_until
        )), '[]'::jsonb)
        FROM aip_formal_assessments fa
        JOIN aip_levels l ON l.id = fa.level_id
        WHERE fa.candidate_id = p_candidate_id
        AND fa.status = 'available'
        AND (fa.available_until IS NULL OR fa.available_until > now())
      ),
      'pending_requests', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
          'id', ar.id, 'level', l.name, 'status', ar.status, 'requested_at', ar.requested_at
        )), '[]'::jsonb)
        FROM aip_assessment_requests ar
        JOIN aip_levels l ON l.id = ar.level_id
        WHERE ar.candidate_id = p_candidate_id AND ar.status IN ('pending','approved')
      ),
      'completed_assessments', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
          'level', l.name, 'score', ps.score_percentage, 'passed', ps.passed,
          'date', ps.completed_at, 'assessor', a.display_name
        ) ORDER BY ps.completed_at DESC), '[]'::jsonb)
        FROM aip_proctored_sessions ps
        JOIN aip_formal_assessments fa ON fa.id = ps.formal_assessment_id
        JOIN aip_levels l ON l.id = fa.level_id
        LEFT JOIN aip_assessors a ON a.id = ps.assessor_id
        WHERE ps.candidate_id = p_candidate_id AND ps.completed_at IS NOT NULL
      )
    )
    FROM aip_candidates c
    LEFT JOIN aip_facilities f ON f.id = c.facility_id
    LEFT JOIN aip_levels kl ON kl.id = c.knowledge_level_id
    LEFT JOIN aip_levels sl ON sl.id = c.script_level_id
    LEFT JOIN aip_levels pl ON pl.id = c.practice_level_id
    LEFT JOIN aip_levels ob ON ob.id = c.overall_belt_id
    WHERE c.id = p_candidate_id
  );
END;
$$;


ALTER FUNCTION "public"."aip_get_candidate_profile"("p_candidate_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_get_flashcard_deck"("p_level_id" "uuid", "p_candidate_email" "text" DEFAULT NULL::"text", "p_deck_type" "text" DEFAULT 'questions'::"text", "p_count" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cards JSONB;
BEGIN
  IF p_deck_type = 'scripts' OR p_deck_type = 'all' THEN
    -- Script flashcards: front = script name/number, back = function + approved language
    SELECT jsonb_agg(
      jsonb_build_object(
        'card_id', s.id,
        'card_type', 'script',
        'front', 'Script ' || s.script_number || ': ' || s.script_name,
        'back', COALESCE(s.primary_function, '') || 
          CASE WHEN s.approved_language IS NOT NULL 
            THEN E'\n\nApproved Language: ' || s.approved_language 
            ELSE '' END ||
          CASE WHEN array_length(s.forbidden_phrases, 1) > 0 
            THEN E'\n\nForbidden: ' || array_to_string(s.forbidden_phrases, ', ')
            ELSE '' END,
        'difficulty', 'medium'
      ) ORDER BY random()
    )
    INTO v_cards
    FROM aip_scripts s
    WHERE s.belt_level_id = p_level_id
      AND s.is_active = true;
  END IF;

  IF p_deck_type = 'questions' OR p_deck_type = 'all' THEN
    -- Question flashcards: front = question, back = answer
    WITH q_cards AS (
      SELECT 
        q.id as card_id,
        'question' as card_type,
        q.question_text as front,
        COALESCE(a.answer_text, 'Answer pending review') as back,
        q.difficulty::TEXT as difficulty,
        fp.status as progress_status,
        fp.next_review_at
      FROM aip_questions q
      LEFT JOIN aip_answers a ON a.question_id = q.id AND a.sort_order = 0
      LEFT JOIN aip_flashcard_progress fp 
        ON fp.card_source_id = q.id 
        AND fp.card_source_type = 'question'
        AND fp.candidate_email = p_candidate_email
      WHERE q.level_id = p_level_id
        AND q.is_active = true AND q.is_approved = true
        AND a.id IS NOT NULL  -- Only include questions WITH answers
      ORDER BY
        -- Spaced repetition: due cards first, then new, then mastered
        CASE 
          WHEN fp.status IS NULL THEN 1  -- New cards
          WHEN fp.status = 'learning' AND (fp.next_review_at IS NULL OR fp.next_review_at <= now()) THEN 0  -- Due for review
          WHEN fp.status = 'mastered' AND (fp.next_review_at IS NULL OR fp.next_review_at <= now()) THEN 2  -- Mastered but due
          ELSE 3  -- Not yet due
        END,
        random()
      LIMIT p_count
    )
    SELECT COALESCE(v_cards, '[]'::jsonb) || jsonb_agg(
      jsonb_build_object(
        'card_id', card_id,
        'card_type', card_type,
        'front', front,
        'back', back,
        'difficulty', difficulty,
        'progress_status', COALESCE(progress_status::TEXT, 'new')
      )
    )
    INTO v_cards
    FROM q_cards;
  END IF;

  RETURN jsonb_build_object(
    'deck_size', COALESCE(jsonb_array_length(v_cards), 0),
    'cards', COALESCE(v_cards, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."aip_get_flashcard_deck"("p_level_id" "uuid", "p_candidate_email" "text", "p_deck_type" "text", "p_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_get_question_answers"("p_question_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', a.id,
        'answer_text', a.answer_text,
        'answer_component', a.answer_component,
        'sort_order', a.sort_order,
        'source_reference', a.source_reference
      ) ORDER BY a.sort_order
    )
    FROM aip_answers a
    WHERE a.question_id = p_question_id
  );
END;
$$;


ALTER FUNCTION "public"."aip_get_question_answers"("p_question_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_get_script_drill"("p_level_id" "uuid" DEFAULT NULL::"uuid", "p_count" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_agg(jsonb_build_object(
      'script_id', s.id,
      'script_number', s.script_number,
      'script_name', s.script_name,
      'primary_function', s.primary_function,
      'approved_language', s.approved_language,
      'forbidden_phrases', s.forbidden_phrases,
      'belt_code', l.code
    ) ORDER BY random())
    FROM aip_scripts s
    JOIN aip_levels l ON l.id = s.belt_level_id
    WHERE s.is_active = true
      AND (p_level_id IS NULL OR s.belt_level_id = p_level_id)
    LIMIT p_count
  );
END;
$$;


ALTER FUNCTION "public"."aip_get_script_drill"("p_level_id" "uuid", "p_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_get_weak_areas"("p_candidate_email" "text", "p_level_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_agg(jsonb_build_object(
      'category', category,
      'total', total,
      'correct', correct,
      'accuracy', accuracy,
      'is_weak', accuracy < 80
    ) ORDER BY accuracy ASC)
    FROM (
      SELECT 
        q.content_category::TEXT as category,
        COUNT(*) as total,
        COUNT(*) FILTER (WHERE qr.is_correct = true) as correct,
        ROUND(
          COUNT(*) FILTER (WHERE qr.is_correct = true)::NUMERIC / 
          NULLIF(COUNT(*), 0) * 100, 1
        ) as accuracy
      FROM aip_question_responses qr
      JOIN aip_assessment_attempts a ON a.id = qr.attempt_id
      JOIN aip_questions q ON q.id = qr.question_id
      WHERE a.candidate_email = p_candidate_email
        AND (p_level_id IS NULL OR a.level_id = p_level_id)
        AND qr.is_correct IS NOT NULL
      GROUP BY q.content_category
      HAVING COUNT(*) >= 3  -- Minimum sample for meaningful data
    ) stats
  );
END;
$$;


ALTER FUNCTION "public"."aip_get_weak_areas"("p_candidate_email" "text", "p_level_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_request_assessment"("p_candidate_id" "uuid", "p_level_id" "uuid", "p_request_type" "text" DEFAULT 'formal_exam'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_id UUID;
BEGIN
  -- Check for existing pending request
  IF EXISTS (SELECT 1 FROM aip_assessment_requests WHERE candidate_id = p_candidate_id AND level_id = p_level_id AND status = 'pending') THEN
    RETURN jsonb_build_object('error','You already have a pending request for this level');
  END IF;
  INSERT INTO aip_assessment_requests (candidate_id, level_id, request_type)
  VALUES (p_candidate_id, p_level_id, p_request_type)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('success', true, 'request_id', v_id);
END;
$$;


ALTER FUNCTION "public"."aip_request_assessment"("p_candidate_id" "uuid", "p_level_id" "uuid", "p_request_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_set_candidate_level"("p_admin_id" "uuid", "p_candidate_id" "uuid", "p_dimension" "text", "p_new_level_id" "uuid", "p_reason" "text" DEFAULT 'admin_override'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE v_old UUID; v_col TEXT;
BEGIN
  v_col := p_dimension || '_level_id';
  IF p_dimension = 'overall_belt' THEN v_col := 'overall_belt_id'; END IF;
  -- Get current level
  EXECUTE 'SELECT ' || v_col || ' FROM aip_candidates WHERE id = $1' INTO v_old USING p_candidate_id;
  -- Update
  EXECUTE 'UPDATE aip_candidates SET ' || v_col || ' = $1, updated_at = now() WHERE id = $2' USING p_new_level_id, p_candidate_id;
  -- Log history
  INSERT INTO aip_candidate_level_history (candidate_id, dimension, from_level_id, to_level_id, reason, changed_by)
  VALUES (p_candidate_id, p_dimension, v_old, p_new_level_id, p_reason, p_admin_id);
  RETURN jsonb_build_object('success', true);
END;
$_$;


ALTER FUNCTION "public"."aip_set_candidate_level"("p_admin_id" "uuid", "p_candidate_id" "uuid", "p_dimension" "text", "p_new_level_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_start_proctored_session"("p_formal_assessment_id" "uuid", "p_candidate_pin" "text", "p_assessor_email" "text", "p_assessor_pin" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_fa aip_formal_assessments%ROWTYPE; v_cand aip_candidates%ROWTYPE; v_ass aip_assessors%ROWTYPE; v_sid UUID; v_aid UUID;
BEGIN
  SELECT * INTO v_fa FROM aip_formal_assessments WHERE id=p_formal_assessment_id AND status='available';
  IF v_fa.id IS NULL THEN RETURN jsonb_build_object('error','Assessment not available'); END IF;
  SELECT * INTO v_cand FROM aip_candidates WHERE id=v_fa.candidate_id;
  IF v_cand.pin!=p_candidate_pin THEN RETURN jsonb_build_object('error','Invalid candidate PIN'); END IF;
  SELECT * INTO v_ass FROM aip_assessors WHERE email=lower(p_assessor_email) AND pin=p_assessor_pin AND facility_id=v_cand.facility_id AND is_active;
  IF v_ass.id IS NULL THEN RETURN jsonb_build_object('error','Invalid assessor credentials'); END IF;
  INSERT INTO aip_assessment_attempts (candidate_email,level_id,mode,total_questions,config) VALUES (v_cand.email,v_fa.level_id,'timed_test',v_fa.question_count,jsonb_build_object('formal',true,'proctored',true)) RETURNING id INTO v_aid;
  INSERT INTO aip_proctored_sessions (formal_assessment_id,candidate_id,candidate_pin_verified,assessor_id,assessor_pin_verified,facility_id,attempt_id) VALUES (p_formal_assessment_id,v_cand.id,true,v_ass.id,true,v_cand.facility_id,v_aid) RETURNING id INTO v_sid;
  UPDATE aip_formal_assessments SET status='in_progress' WHERE id=p_formal_assessment_id;
  RETURN jsonb_build_object('success',true,'session_id',v_sid,'attempt_id',v_aid,
    'candidate_name',v_cand.first_name||' '||v_cand.last_name,'assessor_name',v_ass.display_name,
    'facility',(SELECT name FROM aip_facilities WHERE id=v_cand.facility_id),
    'level',(SELECT name FROM aip_levels WHERE id=v_fa.level_id));
END; $$;


ALTER FUNCTION "public"."aip_start_proctored_session"("p_formal_assessment_id" "uuid", "p_candidate_pin" "text", "p_assessor_email" "text", "p_assessor_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_submit_quiz"("p_attempt_id" "uuid", "p_responses" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_response JSONB;
  v_question_id UUID;
  v_candidate_answer TEXT;
  v_correct_answer TEXT;
  v_is_correct BOOLEAN;
  v_correct_count INTEGER := 0;
  v_total INTEGER := 0;
  v_score_pct DECIMAL(5,2);
  v_passed BOOLEAN;
  v_passing_threshold INTEGER;
  v_level_id UUID;
  v_category_stats JSONB := '{}'::jsonb;
  v_cat TEXT;
  v_results JSONB := '[]'::jsonb;
BEGIN
  -- Get attempt info
  SELECT a.level_id, l.passing_threshold
  INTO v_level_id, v_passing_threshold
  FROM aip_assessment_attempts a
  JOIN aip_levels l ON l.id = a.level_id
  WHERE a.id = p_attempt_id;

  IF v_level_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Attempt not found');
  END IF;

  -- Process each response
  FOR v_response IN SELECT jsonb_array_elements(p_responses)
  LOOP
    v_question_id := (v_response->>'question_id')::UUID;
    v_candidate_answer := v_response->>'candidate_answer';
    v_total := v_total + 1;

    -- Get correct answer (first answer component)
    SELECT answer_text INTO v_correct_answer
    FROM aip_answers
    WHERE question_id = v_question_id
    AND (answer_component = 'full_answer' OR answer_component = 'expected_response')
    ORDER BY sort_order
    LIMIT 1;

    -- Simple scoring: mark as needs_manual_scoring for open-ended
    -- For now, all short_answer types need manual scoring
    v_is_correct := NULL;

    -- Save response
    INSERT INTO aip_question_responses (attempt_id, question_id, candidate_answer, is_correct, needs_manual_scoring)
    VALUES (p_attempt_id, v_question_id, v_candidate_answer, v_is_correct, true);

    -- Get category for stats
    SELECT content_category::TEXT INTO v_cat FROM aip_questions WHERE id = v_question_id;

    -- Build per-question result with answer (for practice mode)
    v_results := v_results || jsonb_build_object(
      'question_id', v_question_id,
      'candidate_answer', v_candidate_answer,
      'correct_answer', v_correct_answer,
      'needs_manual_scoring', true
    );
  END LOOP;

  -- Update attempt record
  UPDATE aip_assessment_attempts
  SET completed_at = now(),
      total_questions = v_total,
      correct_answers = v_correct_count,
      score_percentage = 0, -- Will be calculated after manual scoring
      passed = NULL -- Pending manual scoring
  WHERE id = p_attempt_id;

  RETURN jsonb_build_object(
    'attempt_id', p_attempt_id,
    'total_questions', v_total,
    'status', 'submitted_pending_review',
    'message', 'Responses saved. Open-ended questions require facilitator review for scoring.',
    'results', v_results
  );
END;
$$;


ALTER FUNCTION "public"."aip_submit_quiz"("p_attempt_id" "uuid", "p_responses" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_submit_quiz"("p_attempt_id" "uuid", "p_responses" "jsonb", "p_candidate_email" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_response JSONB;
  v_qid UUID;
  v_ans TEXT;
  v_correct TEXT;
  v_fail TEXT;
  v_total INTEGER := 0;
  v_level_id UUID;
  v_results JSONB := '[]'::jsonb;
BEGIN
  SELECT level_id INTO v_level_id FROM aip_assessment_attempts WHERE id = p_attempt_id;
  IF v_level_id IS NULL THEN RETURN jsonb_build_object('error','Attempt not found'); END IF;

  -- Update candidate email on attempt
  IF p_candidate_email IS NOT NULL THEN
    UPDATE aip_assessment_attempts SET candidate_email = p_candidate_email WHERE id = p_attempt_id;
  END IF;

  FOR v_response IN SELECT jsonb_array_elements(p_responses)
  LOOP
    v_qid := (v_response->>'question_id')::UUID;
    v_ans := v_response->>'candidate_answer';
    v_total := v_total + 1;

    -- Get correct answer (expected_response or full_answer)
    SELECT answer_text INTO v_correct FROM aip_answers
    WHERE question_id = v_qid AND answer_component IN ('full_answer','expected_response')
    ORDER BY sort_order LIMIT 1;

    -- Get fail indicator if exists
    SELECT answer_text INTO v_fail FROM aip_answers
    WHERE question_id = v_qid AND answer_component = 'fail_indicator'
    ORDER BY sort_order LIMIT 1;

    INSERT INTO aip_question_responses (attempt_id, question_id, candidate_answer, is_correct, needs_manual_scoring)
    VALUES (p_attempt_id, v_qid, v_ans, NULL, true);

    v_results := v_results || jsonb_build_object(
      'question_id', v_qid,
      'candidate_answer', v_ans,
      'correct_answer', v_correct,
      'fail_indicator', v_fail
    );
  END LOOP;

  UPDATE aip_assessment_attempts
  SET completed_at = now(), total_questions = v_total, correct_answers = 0, score_percentage = 0, passed = NULL
  WHERE id = p_attempt_id;

  RETURN jsonb_build_object('attempt_id', p_attempt_id, 'total_questions', v_total, 'results', v_results);
END;
$$;


ALTER FUNCTION "public"."aip_submit_quiz"("p_attempt_id" "uuid", "p_responses" "jsonb", "p_candidate_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_submit_quiz"("p_attempt_id" "uuid", "p_responses" "jsonb", "p_candidate_email" "text" DEFAULT NULL::"text", "p_time_spent" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_resp JSONB;
  v_qid UUID;
  v_ans TEXT;
  v_correct TEXT;
  v_qtype TEXT;
  v_is_correct BOOLEAN;
  v_correct_count INTEGER := 0;
  v_total INTEGER := 0;
  v_score DECIMAL(5,2);
  v_passed BOOLEAN;
  v_threshold INTEGER;
  v_level_id UUID;
  v_mode TEXT;
  v_results JSONB := '[]'::jsonb;
  v_cat TEXT;
  v_cat_stats JSONB := '{}'::jsonb;
BEGIN
  SELECT a.level_id, a.mode::TEXT, l.passing_threshold
  INTO v_level_id, v_mode, v_threshold
  FROM aip_assessment_attempts a
  JOIN aip_levels l ON l.id = a.level_id
  WHERE a.id = p_attempt_id;

  IF v_level_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Attempt not found');
  END IF;

  -- Update candidate email on attempt
  IF p_candidate_email IS NOT NULL THEN
    UPDATE aip_assessment_attempts SET candidate_email = p_candidate_email WHERE id = p_attempt_id;
  END IF;

  FOR v_resp IN SELECT jsonb_array_elements(p_responses)
  LOOP
    v_qid := (v_resp->>'question_id')::UUID;
    v_ans := v_resp->>'candidate_answer';
    v_total := v_total + 1;

    -- Get question type and correct answer
    SELECT q.question_type::TEXT, a.answer_text
    INTO v_qtype, v_correct
    FROM aip_questions q
    LEFT JOIN aip_answers a ON a.question_id = q.id AND a.sort_order = 0
      AND (a.answer_component = 'full_answer' OR a.answer_component = 'expected_response')
    WHERE q.id = v_qid;

    -- Auto-score where possible
    v_is_correct := NULL;
    IF v_qtype IN ('true_false') AND v_correct IS NOT NULL THEN
      v_is_correct := lower(trim(v_ans)) = lower(trim(v_correct));
      IF v_is_correct THEN v_correct_count := v_correct_count + 1; END IF;
    ELSIF v_qtype IN ('multiple_choice') THEN
      -- Check answer_options
      SELECT EXISTS(
        SELECT 1 FROM aip_answer_options
        WHERE question_id = v_qid AND is_correct = true
        AND lower(trim(option_text)) = lower(trim(v_ans))
      ) INTO v_is_correct;
      IF v_is_correct THEN v_correct_count := v_correct_count + 1; END IF;
    END IF;

    -- Save response
    INSERT INTO aip_question_responses (attempt_id, question_id, candidate_answer, is_correct, needs_manual_scoring)
    VALUES (p_attempt_id, v_qid, v_ans, v_is_correct, v_is_correct IS NULL);

    -- Track category stats
    SELECT content_category::TEXT INTO v_cat FROM aip_questions WHERE id = v_qid;
    IF v_cat IS NOT NULL THEN
      v_cat_stats := v_cat_stats || jsonb_build_object(v_cat,
        jsonb_build_object(
          'total', COALESCE((v_cat_stats->v_cat->>'total')::int, 0) + 1,
          'correct', COALESCE((v_cat_stats->v_cat->>'correct')::int, 0) + CASE WHEN v_is_correct THEN 1 ELSE 0 END
        )
      );
    END IF;

    -- Build result (include answer for practice mode)
    v_results := v_results || jsonb_build_object(
      'question_id', v_qid,
      'candidate_answer', v_ans,
      'correct_answer', CASE WHEN v_mode = 'practice_quiz' THEN v_correct ELSE NULL END,
      'is_correct', v_is_correct,
      'needs_manual_scoring', v_is_correct IS NULL
    );
  END LOOP;

  -- Calculate score
  v_score := CASE WHEN v_total > 0 THEN ROUND(v_correct_count::NUMERIC / v_total * 100, 1) ELSE 0 END;
  v_passed := v_score >= v_threshold;

  -- Update attempt
  UPDATE aip_assessment_attempts
  SET completed_at = now(),
      total_questions = v_total,
      correct_answers = v_correct_count,
      score_percentage = v_score,
      passed = v_passed,
      time_spent_seconds = p_time_spent,
      category_breakdown = v_cat_stats,
      candidate_email = COALESCE(p_candidate_email, candidate_email)
  WHERE id = p_attempt_id;

  RETURN jsonb_build_object(
    'attempt_id', p_attempt_id,
    'total_questions', v_total,
    'correct_answers', v_correct_count,
    'score_percentage', v_score,
    'passed', v_passed,
    'passing_threshold', v_threshold,
    'mode', v_mode,
    'show_answers', v_mode = 'practice_quiz',
    'results', CASE WHEN v_mode = 'practice_quiz' THEN v_results ELSE '[]'::jsonb END,
    'category_breakdown', v_cat_stats
  );
END;
$$;


ALTER FUNCTION "public"."aip_submit_quiz"("p_attempt_id" "uuid", "p_responses" "jsonb", "p_candidate_email" "text", "p_time_spent" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aip_update_flashcard_progress"("p_candidate_email" "text", "p_card_source_id" "uuid", "p_card_source_type" "text" DEFAULT 'question'::"text", "p_got_it" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_record aip_flashcard_progress%ROWTYPE;
  v_new_status aip_flashcard_status;
  v_next_review TIMESTAMPTZ;
BEGIN
  -- Upsert progress record
  INSERT INTO aip_flashcard_progress (candidate_email, card_source_type, card_source_id, times_seen, times_correct, consecutive_correct, last_seen_at, status)
  VALUES (p_candidate_email, p_card_source_type, p_card_source_id, 1, 
    CASE WHEN p_got_it THEN 1 ELSE 0 END,
    CASE WHEN p_got_it THEN 1 ELSE 0 END,
    now(), 'learning')
  ON CONFLICT (candidate_email, card_source_type, card_source_id)
  DO UPDATE SET
    times_seen = aip_flashcard_progress.times_seen + 1,
    times_correct = aip_flashcard_progress.times_correct + CASE WHEN p_got_it THEN 1 ELSE 0 END,
    consecutive_correct = CASE WHEN p_got_it THEN aip_flashcard_progress.consecutive_correct + 1 ELSE 0 END,
    last_seen_at = now(),
    updated_at = now()
  RETURNING * INTO v_record;

  -- Determine new status and next review
  IF v_record.consecutive_correct >= 3 THEN
    v_new_status := 'mastered';
    v_next_review := now() + interval '7 days';
  ELSIF v_record.times_seen >= 1 THEN
    v_new_status := 'learning';
    IF p_got_it THEN
      v_next_review := now() + interval '1 day' * v_record.consecutive_correct;
    ELSE
      v_next_review := now() + interval '10 minutes';
    END IF;
  ELSE
    v_new_status := 'new';
    v_next_review := now();
  END IF;

  UPDATE aip_flashcard_progress
  SET status = v_new_status, next_review_at = v_next_review
  WHERE id = v_record.id;

  RETURN jsonb_build_object(
    'card_source_id', p_card_source_id,
    'status', v_new_status::TEXT,
    'consecutive_correct', v_record.consecutive_correct,
    'times_seen', v_record.times_seen,
    'next_review_at', v_next_review
  );
END;
$$;


ALTER FUNCTION "public"."aip_update_flashcard_progress"("p_candidate_email" "text", "p_card_source_id" "uuid", "p_card_source_type" "text", "p_got_it" boolean) OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."david_facility_access" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" character varying NOT NULL,
    "is_active" boolean DEFAULT false,
    "tier" character varying DEFAULT 'base'::character varying,
    "max_monthly_tokens" integer DEFAULT 500000,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "custom_directive" "text",
    "usage_tier" "text" DEFAULT 'included'::"text" NOT NULL,
    "questions_allowance" integer DEFAULT 250 NOT NULL,
    "questions_consumed" integer DEFAULT 0 NOT NULL,
    "reserve_consumed" integer DEFAULT 0 NOT NULL,
    "period_start" "date" DEFAULT ("date_trunc"('month'::"text", "now"()))::"date" NOT NULL,
    "tokens_consumed" bigint DEFAULT 0 NOT NULL,
    CONSTRAINT "david_facility_access_tier_check" CHECK ((("tier")::"text" = ANY ((ARRAY['base'::character varying, 'premium'::character varying, 'supreme'::character varying])::"text"[]))),
    CONSTRAINT "david_facility_access_usage_tier_chk" CHECK (("usage_tier" = ANY (ARRAY['included'::"text", 'starter'::"text", 'standard'::"text", 'power'::"text"])))
);


ALTER TABLE "public"."david_facility_access" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."david_consume_question"("p_facility_id" "text", "p_is_reserve" boolean DEFAULT false, "p_tokens" integer DEFAULT 0) RETURNS "public"."david_facility_access"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  rec public.david_facility_access;
  m   date := date_trunc('month', now())::date;
BEGIN
  SELECT * INTO rec FROM public.david_facility_access
    WHERE facility_id = p_facility_id
    FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF rec.period_start IS NULL OR rec.period_start < m THEN
    rec.questions_consumed := 0;
    rec.reserve_consumed   := 0;
    rec.tokens_consumed    := 0;
    rec.period_start       := m;
  END IF;
  UPDATE public.david_facility_access
    SET questions_consumed = rec.questions_consumed + 1,
        reserve_consumed   = rec.reserve_consumed + (CASE WHEN p_is_reserve THEN 1 ELSE 0 END),
        tokens_consumed    = rec.tokens_consumed + GREATEST(p_tokens, 0),
        period_start       = m,
        updated_at         = now()
    WHERE facility_id = p_facility_id
    RETURNING * INTO rec;
  RETURN rec;
END;
$$;


ALTER FUNCTION "public"."david_consume_question"("p_facility_id" "text", "p_is_reserve" boolean, "p_tokens" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."david_get_quota"("p_facility_id" "text") RETURNS "public"."david_facility_access"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  rec public.david_facility_access;
  m   date := date_trunc('month', now())::date;
BEGIN
  SELECT * INTO rec FROM public.david_facility_access
    WHERE facility_id = p_facility_id
    FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NULL;                         -- no access row (e.g. master-admin-global) → caller skips metering
  END IF;
  IF rec.period_start IS NULL OR rec.period_start < m THEN
    UPDATE public.david_facility_access
      SET questions_consumed = 0,
          reserve_consumed   = 0,
          tokens_consumed    = 0,
          period_start       = m,
          updated_at         = now()
      WHERE facility_id = p_facility_id
      RETURNING * INTO rec;
  END IF;
  RETURN rec;
END;
$$;


ALTER FUNCTION "public"."david_get_quota"("p_facility_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."david_usage_by_app_mtd"() RETURNS TABLE("facility_id" "text", "facility_name" "text", "app" "text", "questions" bigint, "tokens" bigint, "cost" numeric, "questions_mtd" bigint, "tokens_mtd" bigint, "cost_mtd" numeric, "questions_all" bigint, "tokens_all" bigint, "cost_all" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM sbd_portal_users u
    WHERE u.auth_uid = auth.uid() AND u.role = 'master_admin'
  ) THEN
    RAISE EXCEPTION 'Forbidden: master admin only';
  END IF;

  RETURN QUERY
  WITH agg AS (
    SELECT
      l.facility_id::text AS fid,
      COALESCE(f.name,
        CASE WHEN l.facility_id = 'master-admin-global'
             THEN 'SIPS Internal (Master)' ELSE l.facility_id::text END) AS fname,
      l.app AS app,
      COUNT(*) FILTER (WHERE l.created_at >= date_trunc('month', now()))::bigint AS q_mtd,
      COALESCE(SUM(l.prompt_tokens + l.completion_tokens) FILTER (WHERE l.created_at >= date_trunc('month', now())), 0)::bigint AS t_mtd,
      ROUND(COALESCE(SUM(l.cost) FILTER (WHERE l.created_at >= date_trunc('month', now())), 0)::numeric, 4) AS c_mtd,
      COUNT(*)::bigint AS q_all,
      COALESCE(SUM(l.prompt_tokens + l.completion_tokens), 0)::bigint AS t_all,
      ROUND(COALESCE(SUM(l.cost), 0)::numeric, 4) AS c_all
    FROM david_usage_logs l
    LEFT JOIN facilities f ON f.id::text = l.facility_id
    WHERE l.source = 'chat'          -- <<< THE FIX: assessment rows never reach the platform cards.
    GROUP BY l.facility_id, f.name, l.app
  )
  SELECT agg.fid, agg.fname, agg.app,
         q_mtd, t_mtd, c_mtd,          -- legacy names = month-to-date
         q_mtd, t_mtd, c_mtd,          -- _mtd
         q_all, t_all, c_all           -- _all
  FROM agg
  ORDER BY agg.fname, agg.app;
END;
$$;


ALTER FUNCTION "public"."david_usage_by_app_mtd"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."exec_sql"("sql_query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    result jsonb;
BEGIN
    IF sql_query ILIKE 'SELECT%' THEN
        EXECUTE format('SELECT json_agg(t) FROM (%s) t', sql_query) INTO result;
        RETURN COALESCE(result, '[]'::jsonb);
    ELSE
        EXECUTE sql_query;
        RETURN '{"status": "success"}'::jsonb;
    END IF;
EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Execution Failed: %', SQLERRM;
END;
$$;


ALTER FUNCTION "public"."exec_sql"("sql_query" "text") OWNER TO "postgres";


