CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sbd_approve_registration"("p_registration_id" "uuid", "p_facility_id" "text", "p_reviewed_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_reg record;
BEGIN
  SELECT * INTO v_reg FROM public.sbd_pending_registrations WHERE id = p_registration_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Registration not found';
  END IF;
  IF v_reg.status != 'pending' THEN
    RAISE EXCEPTION 'Registration already processed';
  END IF;

  -- Create facility
  INSERT INTO public.sbd_facilities(id, name, location, department, contact_name, contact_email, since)
  VALUES (
    p_facility_id,
    v_reg.facility_name,
    v_reg.location,
    v_reg.department,
    v_reg.contact_name,
    v_reg.contact_email,
    to_char(now(), 'Mon YYYY')
  );

  -- Create portal user for the facility
  INSERT INTO public.sbd_portal_users(email, role, name, title, facility_id, initials)
  VALUES (
    v_reg.contact_email,
    'hospital',
    v_reg.contact_name,
    'Dept. Manager',
    p_facility_id,
    upper(left(split_part(v_reg.contact_name, ' ', 1), 1) || left(split_part(v_reg.contact_name, ' ', 2), 1))
  );

  -- Mark registration approved
  UPDATE public.sbd_pending_registrations
  SET status = 'approved', reviewed_by = p_reviewed_by, reviewed_at = now()
  WHERE id = p_registration_id;

  RETURN jsonb_build_object('success', true, 'facility_id', p_facility_id);
END;
$$;


ALTER FUNCTION "public"."sbd_approve_registration"("p_registration_id" "uuid", "p_facility_id" "text", "p_reviewed_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sbd_bulk_insert_staff"("p_staff" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_inserted integer := 0;
  v_errors jsonb := '[]';
  v_row jsonb;
  v_idx integer := 0;
BEGIN
  FOR v_row IN SELECT * FROM jsonb_array_elements(p_staff)
  LOOP
    v_idx := v_idx + 1;
    BEGIN
      INSERT INTO public.sbd_staff(
        facility_id, first_name, last_name, role, belt, belt_since, stars,
        cur_comp, cur_sim, cur_obs, nxt_comp, nxt_sim, nxt_obs,
        ps_enrolled, ps_done, ps_track, ps_module, promo_recommended
      ) VALUES (
        v_row->>'facility_id',
        v_row->>'first_name',
        v_row->>'last_name',
        v_row->>'role',
        COALESCE(v_row->>'belt', 'White'),
        COALESCE((v_row->>'belt_since')::date, CURRENT_DATE),
        COALESCE((v_row->>'stars')::integer, 0),
        v_row->>'cur_comp', v_row->>'cur_sim', v_row->>'cur_obs',
        v_row->>'nxt_comp', v_row->>'nxt_sim', v_row->>'nxt_obs',
        COALESCE((v_row->>'ps_enrolled')::boolean, false),
        COALESCE((v_row->>'ps_done')::boolean, false),
        COALESCE(v_row->>'ps_track', ''),
        COALESCE(v_row->>'ps_module', ''),
        COALESCE((v_row->>'promo_recommended')::boolean, false)
      );
      v_inserted := v_inserted + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors || jsonb_build_object('row', v_idx, 'error', SQLERRM);
    END;
  END LOOP;

  RETURN jsonb_build_object('inserted', v_inserted, 'errors', v_errors);
END;
$$;


ALTER FUNCTION "public"."sbd_bulk_insert_staff"("p_staff" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sbd_calc_points"("p_staff_id" integer) RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_staff record;
  v_pts integer := 0;
  v_belt_idx integer;
  belt_order text[] := ARRAY['White','Yellow','Green','Blue','Brown','Black'];
  belt_points integer[] := ARRAY[100, 250, 500, 1000, 2000, 5000];
  i integer;
BEGIN
  SELECT * INTO v_staff FROM public.sbd_staff WHERE id = p_staff_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  v_belt_idx := array_position(belt_order, v_staff.belt);

  -- Belt points for all earned belts up to current
  FOR i IN 1..v_belt_idx LOOP
    v_pts := v_pts + belt_points[i];
  END LOOP;

  -- Gate points (current tier)
  IF v_staff.cur_comp = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.cur_sim = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.cur_obs = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.cur_comp = 'fail' THEN v_pts := v_pts - 10; END IF;
  IF v_staff.cur_sim = 'fail' THEN v_pts := v_pts - 10; END IF;
  IF v_staff.cur_obs = 'fail' THEN v_pts := v_pts - 10; END IF;

  -- Gate points (next tier)
  IF v_staff.nxt_comp = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.nxt_sim = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.nxt_obs = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.nxt_comp = 'fail' THEN v_pts := v_pts - 10; END IF;
  IF v_staff.nxt_sim = 'fail' THEN v_pts := v_pts - 10; END IF;
  IF v_staff.nxt_obs = 'fail' THEN v_pts := v_pts - 10; END IF;

  -- Star bonus
  v_pts := v_pts + (v_staff.stars * 25);

  -- Position school bonus
  IF v_staff.ps_done THEN v_pts := v_pts + 200;
  ELSIF v_staff.ps_enrolled THEN v_pts := v_pts + 50;
  END IF;

  RETURN GREATEST(v_pts, 0);
END;
$$;


ALTER FUNCTION "public"."sbd_calc_points"("p_staff_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sbd_can_approve_assessment"("p_fid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists(
    select 1 from sbd_portal_users p
    where p.auth_uid = auth.uid()
      and coalesce((p.capabilities->>'approve_assessment')::boolean, false)
      and (
        not (p.capabilities ? 'approve_assessment_facilities')
        or jsonb_typeof(p.capabilities->'approve_assessment_facilities') is distinct from 'array'
        or jsonb_array_length(p.capabilities->'approve_assessment_facilities') = 0
        or p_fid::text in (
             select jsonb_array_elements_text(p.capabilities->'approve_assessment_facilities'))
      ));
$$;


