CREATE OR REPLACE FUNCTION "public"."sbd_guard_portal_user_privileges"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  jwt_role  text;
  privileged_change boolean;
begin
  privileged_change :=
       new.role                  is distinct from old.role
    or new.capabilities          is distinct from old.capabilities
    or new.facility_id           is distinct from old.facility_id
    or new.assigned_facility_ids is distinct from old.assigned_facility_ids
    or new.system_id             is distinct from old.system_id
    or new.active                is distinct from old.active
    or new.protected             is distinct from old.protected
    or new.auth_uid              is distinct from old.auth_uid
    or new.staff_id              is distinct from old.staff_id
    or new.email                 is distinct from old.email;

  if not privileged_change then
    return new;
  end if;

  jwt_role := coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb ->> 'role';

  if jwt_role is null or jwt_role = 'service_role' then
    return new;
  end if;

  if public.sbd_is_master_admin() then
    return new;
  end if;

  raise exception
    'Only a master admin can change role, capabilities, facility assignment, account state or identity on a portal user'
    using errcode = '42501';
end $$;


ALTER FUNCTION "public"."sbd_guard_portal_user_privileges"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sbd_guard_portal_user_privileges"() IS 'T53: refuses changes to role, capabilities, facility assignment, account state or identity on sbd_portal_users unless the caller is a master admin, the service role, or has no JWT context. Ordinary profile self-edits (name, initials, title) are unaffected.';



CREATE OR REPLACE FUNCTION "public"."sbd_guard_staff_privileged_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  jwt_role text;
  privileged_change boolean;
begin
  privileged_change :=
       new.belt                     is distinct from old.belt
    or new.stars                    is distinct from old.stars
    or new.since                    is distinct from old.since
    or new.history                  is distinct from old.history
    or new.cur_comp                 is distinct from old.cur_comp
    or new.cur_sim                  is distinct from old.cur_sim
    or new.cur_obs                  is distinct from old.cur_obs
    or new.nxt_comp                 is distinct from old.nxt_comp
    or new.nxt_sim                  is distinct from old.nxt_sim
    or new.nxt_obs                  is distinct from old.nxt_obs
    or new.assessment_gate_override is distinct from old.assessment_gate_override
    or new.window_override          is distinct from old.window_override
    or new.role                     is distinct from old.role
    or new.fid                      is distinct from old.fid
    or new.observer                 is distinct from old.observer
    -- T37: staff.observation_pin is gone; the secret lives in sbd_observer_pins, which
    -- `authenticated` cannot reach at all. observer_pin_set is the flag left behind.
    or new.observer_pin_set         is distinct from old.observer_pin_set
    -- T65: a candidate must not be able to clear their own safety provision.
    or new.dangerous_provisions     is distinct from old.dangerous_provisions;

  if not privileged_change then
    return new;
  end if;

  jwt_role := coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb ->> 'role';

  if jwt_role is null or jwt_role = 'service_role' then
    return new;
  end if;

  if public.sbd_get_user_role() = 'staff_member' then
    raise exception
      'A staff member cannot change their own belt, stars, progress gates, facility, assessment overrides or safety provisions'
      using errcode = '42501';
  end if;

  return new;
end $$;


ALTER FUNCTION "public"."sbd_guard_staff_privileged_columns"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sbd_guard_staff_privileged_columns"() IS 'T24, extended by T65 and T37: refuses a staff_member changing their own belt, stars, since, history, progress gates, overrides, role, facility, observer flag, observer-PIN flag or dangerous provisions. Position School writes that carry stars unchanged still pass, as do all administrator, assessor and service-role writes.';



CREATE OR REPLACE FUNCTION "public"."sbd_is_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    coalesce(auth.jwt()->'app_metadata'->>'role',
             auth.jwt()->>'role')
      in ('master_admin','staff_admin','admin')
    or exists (
      select 1 from public.sbd_portal_users u
      where (u.id = auth.uid() or lower(u.email) = lower(coalesce(auth.jwt()->>'email','')))
        and u.role in ('master_admin','staff_admin','admin')
    )
    or lower(coalesce(auth.jwt()->>'email','')) in
       ('jjacobs@sipsconsults.com','izambrano@sipsconsults.com','dpayne@sipsconsults.com');
$$;


