CREATE OR REPLACE FUNCTION "public"."sbd_is_assessor"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists(select 1 from sbd_portal_users p
                where p.auth_uid = auth.uid()
                  and (p.role = 'assessor' or coalesce((p.capabilities->>'assessor')::boolean, false)));
$$;


ALTER FUNCTION "public"."sbd_is_assessor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sbd_is_assessor"("p_fid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists(
    select 1 from sbd_portal_users p
    where p.auth_uid = auth.uid()
      and ( p.role = 'assessor'
            or coalesce((p.capabilities->>'assessor')::boolean, false) )
      and (
        -- No list, or an empty list, means the grant is system wide. Every holder today.
        not (p.capabilities ? 'assessor_facilities')
        or jsonb_typeof(p.capabilities->'assessor_facilities') is distinct from 'array'
        or jsonb_array_length(p.capabilities->'assessor_facilities') = 0
        -- Scoped grant: the row's facility must be one of the chosen ones. A null p_fid
        -- yields false here, which denies rather than leaks when a caller cannot supply a
        -- facility.
        or p_fid::text in (
             select jsonb_array_elements_text(p.capabilities->'assessor_facilities'))
      ));
$$;


ALTER FUNCTION "public"."sbd_is_assessor"("p_fid" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sbd_is_assessor"("p_fid" "uuid") IS 'T74: is the caller an assessor AT p_fid. An absent or empty capabilities.assessor_facilities list means system wide, preserving every pre-T74 holder. Companion to the zero-arg sbd_is_assessor(), which answers "an assessor at all" and still gates nav visibility.';



