CREATE OR REPLACE FUNCTION "public"."sbd_set_user_capabilities"("p_staff_id" "uuid", "p_caps" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_rows integer;
begin
  if not public.sbd_is_master_admin() then
    raise exception 'Only a master admin can change capabilities';
  end if;

  update public.sbd_portal_users
     set capabilities = coalesce(p_caps, '{}'::jsonb)
   where auth_uid = p_staff_id;

  get diagnostics v_rows = row_count;

  if v_rows = 0 then
    raise exception 'No portal user matches that login id, so no capabilities were changed';
  end if;
end;
$$;


ALTER FUNCTION "public"."sbd_set_user_capabilities"("p_staff_id" "uuid", "p_caps" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sbd_trigger_email_send"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Fire-and-forget async HTTP call to process the email queue
  PERFORM net.http_post(
    url := 'https://mhijaqahbceuahfzezbh.supabase.co/functions/v1/sbd-send-emails',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1oaWphcWFoYmNldWFoZnplemJoIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM4MDkwNzksImV4cCI6MjA4OTM4NTA3OX0.GZcvOFxm4uNdTFPnq-rfwHaMVhWbIJWY7QMYToPa7mQ',
      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1oaWphcWFoYmNldWFoZnplemJoIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM4MDkwNzksImV4cCI6MjA4OTM4NTA3OX0.GZcvOFxm4uNdTFPnq-rfwHaMVhWbIJWY7QMYToPa7mQ'
    ),
    body := '{}'::jsonb
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Never block email queuing if the HTTP call fails
  RETURN NEW;
END;
$$;


