CREATE TABLE IF NOT EXISTS "public"."aip_assessment_attempts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "candidate_id" "uuid",
    "candidate_email" "text",
    "level_id" "uuid",
    "mode" "public"."aip_assessment_mode" NOT NULL,
