);


ALTER TABLE "public"."david_usage_logs" OWNER TO "postgres";


COMMENT ON COLUMN "public"."david_usage_logs"."source" IS 'Which AI system produced this usage row: ''chat'' (David chat, the default) or ''assessment'' (sbd-score-assessment grading). Added by #14 so grading spend is metered separately. Chat readers (david-admin-api GET_METRICS MTD, david_analytics_summary view, david-anomaly-detector) filter source=''chat''. Grading NEVER calls david_consume_question, so the chat allowance is untouched.';



COMMENT ON COLUMN "public"."david_usage_logs"."cached_tokens" IS 'Input tokens served from the prompt cache (cache READ) for this request, as reported by the provider (prompt_tokens_details.cached_tokens / cache_read_input_tokens). Subset of prompt_tokens, billed at a large discount. Added by #16.';



COMMENT ON COLUMN "public"."david_usage_logs"."cache_creation_tokens" IS 'Input tokens WRITTEN to the prompt cache (cache miss / creation) for this request (prompt_tokens_details.cache_write_tokens / cache_creation_input_tokens). Subset of prompt_tokens, billed at a premium. Added by #16.';



CREATE OR REPLACE VIEW "public"."david_analytics_summary" WITH ("security_invoker"='on') AS
 SELECT "facility_id",
    "count"(*) AS "total_requests",
    "sum"(("prompt_tokens" + "completion_tokens")) AS "total_tokens",
    "sum"("cost") AS "total_cost",
    "max"("created_at") AS "last_request_date",
    "sum"("cached_tokens") AS "total_cached_tokens",
    "sum"("cache_creation_tokens") AS "total_cache_creation_tokens"
   FROM "public"."david_usage_logs"
  WHERE ("source" = 'chat'::"text")
  GROUP BY "facility_id";


ALTER VIEW "public"."david_analytics_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."david_analytics_summary" IS 'Chat-only (source=''chat'') usage aggregate read by david-admin-api. MUST stay security_invoker=on (T45/P0-7) — Postgres resets this option on any bare `create or replace view`, so any future edit to this view''s SELECT list must either add `WITH (security_invoker = true)` to that CREATE OR REPLACE, or be immediately followed by `alter view public.david_analytics_summary set (security_invoker = on);` in the same migration.';



