CREATE TABLE IF NOT EXISTS "public"."staff" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "fid" "uuid",
    "first" "text" NOT NULL,
    "last" "text" NOT NULL,
    "role" "text" NOT NULL,
    "belt" "text" NOT NULL,
    "since" "date",
    "stars" integer DEFAULT 0,
    "cur_comp" "text",
    "cur_sim" "text",
    "cur_obs" "text",
    "nxt_comp" "text",
    "nxt_sim" "text",
    "nxt_obs" "text",
    "ps_enrolled" boolean DEFAULT false,
    "ps_done" boolean DEFAULT false,
    "ps_track" "text",
    "ps_mod" "text",
    "ps_tracks" "jsonb" DEFAULT '{}'::"jsonb",
    "promo" boolean DEFAULT false,
    "history" "jsonb" DEFAULT '[]'::"jsonb",
    "oip" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "placement_needed" boolean DEFAULT true,
    "observer" boolean DEFAULT false NOT NULL,
    "practice_scores" "jsonb" DEFAULT '{}'::"jsonb",
    "window_override" "jsonb",
    "assessment_gate_override" "jsonb",
    "sbd_program_years" integer,
    "sbd_cert_years" integer,
    "dangerous_provisions" "jsonb",
    "observer_pin_set" boolean DEFAULT false NOT NULL,
    CONSTRAINT "staff_belt_check" CHECK (("belt" = ANY (ARRAY['None'::"text", 'White'::"text", 'Yellow'::"text", 'Green'::"text", 'Blue'::"text", 'Brown'::"text", 'Black'::"text"]))),
    CONSTRAINT "staff_cur_comp_check" CHECK ((("cur_comp" = ANY (ARRAY['pass'::"text", 'fail'::"text"])) OR ("cur_comp" IS NULL))),
    CONSTRAINT "staff_cur_obs_check" CHECK ((("cur_obs" = ANY (ARRAY['pass'::"text", 'fail'::"text"])) OR ("cur_obs" IS NULL))),
    CONSTRAINT "staff_cur_sim_check" CHECK ((("cur_sim" = ANY (ARRAY['pass'::"text", 'fail'::"text"])) OR ("cur_sim" IS NULL))),
    CONSTRAINT "staff_nxt_comp_check" CHECK ((("nxt_comp" = ANY (ARRAY['pass'::"text", 'fail'::"text"])) OR ("nxt_comp" IS NULL))),
    CONSTRAINT "staff_nxt_obs_check" CHECK ((("nxt_obs" = ANY (ARRAY['pass'::"text", 'fail'::"text"])) OR ("nxt_obs" IS NULL))),
    CONSTRAINT "staff_nxt_sim_check" CHECK ((("nxt_sim" = ANY (ARRAY['pass'::"text", 'fail'::"text"])) OR ("nxt_sim" IS NULL)))
);


ALTER TABLE "public"."staff" OWNER TO "postgres";


COMMENT ON COLUMN "public"."staff"."practice_scores" IS 'Per-belt practice test results keyed by belt name; managed by the staff Study & Practice portal (savePracticeScore).';



COMMENT ON COLUMN "public"."staff"."window_override" IS 'Manual assessment-window override. Null = none. Shape: {until:"YYYY-MM-DD", by:"<uuid>", byName:"<name>", at:"<iso>", reason:"<text>"}. `until` is computed at open-time = now + the belt''s normal open period (BELT_WINDOWS[belt].open weeks). Honored by getWindowStatus() (src/js/logic.js) only after the current-belt gate-lock passes and only while `until` is in the future; then the normal since-based cadence resumes. Never derived from or written to staff.since.';



COMMENT ON COLUMN "public"."staff"."assessment_gate_override" IS 'Master-admin waiver of the practice-test gate for belt assessment requests. null = no waiver; { waived, by, byName, at, reason }. Additive; mirrors window_override.';



COMMENT ON COLUMN "public"."staff"."sbd_program_years" IS 'Years the person has worked in sterile processing. Labelled "Years in SPD" in the interface since 2026-07-28; the column name predates that correction.';



COMMENT ON COLUMN "public"."staff"."sbd_cert_years" IS 'Years the person has held their sterile processing certification. Labelled "Years certified" in the interface since 2026-07-28.';



COMMENT ON COLUMN "public"."staff"."dangerous_provisions" IS 'T65: patient-safety provisions raised when a candidate picks an answer flagged as dangerous. Belt issuance is unaffected; the provision sits on the account until a SIPS admin clears it, and cleared entries are kept so who cleared it and when stays on the record.';



COMMENT ON COLUMN "public"."staff"."observer_pin_set" IS 'T37: true when this staff member has a row in sbd_observer_pins. The PIN value itself is never sent to a browser; this flag is what the roster pill and profile button read.';



