CREATE POLICY "Admins can read all onboarding" ON "public"."user_onboarding" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."sbd_portal_users"
  WHERE (("sbd_portal_users"."auth_uid" = "auth"."uid"()) AND ("sbd_portal_users"."role" = ANY (ARRAY['master_admin'::"text", 'staff_admin'::"text"]))))));



CREATE POLICY "Allow Master Admins to read wiki" ON "public"."david_wiki_pages" FOR SELECT TO "authenticated" USING ((((("auth"."jwt"() -> 'app_metadata'::"text") ->> 'role'::"text") = 'master_admin'::"text") OR (EXISTS ( SELECT 1
   FROM "public"."sbd_portal_users" "u"
  WHERE ((("u"."id" = "auth"."uid"()) OR ("lower"("u"."email") = "lower"(COALESCE(("auth"."jwt"() ->> 'email'::"text"), ''::"text")))) AND ("u"."role" = 'master_admin'::"text")))) OR ("lower"(COALESCE(("auth"."jwt"() ->> 'email'::"text"), ''::"text")) = ANY (ARRAY['jjacobs@sipsconsults.com'::"text", 'izambrano@sipsconsults.com'::"text", 'dpayne@sipsconsults.com'::"text"]))));



CREATE POLICY "Allow all" ON "public"."bb_notifications" USING (true) WITH CHECK (true);



CREATE POLICY "Allow anon full access to hfl_cohorts" ON "public"."hfl_cohorts" USING (true) WITH CHECK (true);



CREATE POLICY "Allow anon full access to hfl_participants" ON "public"."hfl_participants" USING (true) WITH CHECK (true);



CREATE POLICY "Allow anonymous insert on obi_assessments" ON "public"."obi_assessments" FOR INSERT TO "anon" WITH CHECK (true);



CREATE POLICY "Allow anonymous insert on op44_leads" ON "public"."op44_leads" FOR INSERT TO "anon" WITH CHECK (true);



CREATE POLICY "Allow anonymous insert on page_events" ON "public"."page_events" FOR INSERT TO "anon" WITH CHECK (true);



CREATE POLICY "Allow anonymous select on obi_assessments" ON "public"."obi_assessments" FOR SELECT TO "anon" USING (true);



CREATE POLICY "Allow public registration submission" ON "public"."registrations" FOR INSERT TO "anon" WITH CHECK (true);



CREATE POLICY "Facility Admins can view own access" ON "public"."david_facility_access" FOR SELECT USING (true);



CREATE POLICY "Master Admins can manage facility access" ON "public"."david_facility_access" USING ((("auth"."jwt"() ->> 'role'::"text") = 'master_admin'::"text"));



CREATE POLICY "Master Admins can view all usage logs" ON "public"."david_usage_logs" FOR SELECT USING ((("auth"."jwt"() ->> 'role'::"text") = 'master_admin'::"text"));



CREATE POLICY "Master Admins can view audit logs" ON "public"."david_audit_logs" FOR SELECT TO "authenticated" USING ((((("auth"."jwt"() -> 'app_metadata'::"text") ->> 'role'::"text") = 'master_admin'::"text") OR (EXISTS ( SELECT 1
   FROM "public"."sbd_portal_users" "u"
  WHERE ((("u"."id" = "auth"."uid"()) OR ("lower"("u"."email") = "lower"(COALESCE(("auth"."jwt"() ->> 'email'::"text"), ''::"text")))) AND ("u"."role" = 'master_admin'::"text")))) OR ("lower"(COALESCE(("auth"."jwt"() ->> 'email'::"text"), ''::"text")) = ANY (ARRAY['jjacobs@sipsconsults.com'::"text", 'izambrano@sipsconsults.com'::"text", 'dpayne@sipsconsults.com'::"text"]))));



CREATE POLICY "Public read" ON "public"."bb_spd911_episodes" FOR SELECT USING (true);



CREATE POLICY "Service role full access pins" ON "public"."sbd_assessment_pins" USING (("auth"."role"() = 'service_role'::"text"));



CREATE POLICY "Service role full access sessions" ON "public"."sbd_assessment_sessions" USING (("auth"."role"() = 'service_role'::"text"));



CREATE POLICY "Users can delete their own sessions" ON "public"."david_chat_sessions" FOR DELETE USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can insert own usage logs" ON "public"."david_usage_logs" FOR INSERT WITH CHECK (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can insert their own sessions" ON "public"."david_chat_sessions" FOR INSERT WITH CHECK (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can manage their own onboarding" ON "public"."user_onboarding" TO "authenticated" USING (("auth"."uid"() = "user_id")) WITH CHECK (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can manage their own preferences" ON "public"."david_user_preferences" USING (("auth"."uid"() = "user_id"));



CREATE POLICY "Users can update their own sessions" ON "public"."david_chat_sessions" FOR UPDATE USING (("auth"."uid"() = "user_id"));



