-- ============================================================================
-- POST-DUMP ALIGNMENT (what pg_dump cannot express)
-- Output of `supabase db diff --linked --schema public` run against a shadow
-- database built from the dump above, 2026-09-03. Two kinds of statement:
--   1. REVOKEs on ten tables (sbd_rate_limit, sbd_password_resets,
--      sbd_observer_pins, sbd_email_queue, david_audit_logs, ...). A fresh
--      Supabase database grants anon/authenticated on every new table through
--      ALTER DEFAULT PRIVILEGES; production had those grants revoked by the
--      2026-07 security sweeps. pg_dump emits grants, never absences, so the
--      revokes have to be stated here for a rebuild to match.
--   2. Re-statements of two functions and one CHECK constraint whose text is
--      byte-identical to production. The diff tool emits them regardless; they
--      are kept so the file is exactly what the tool verified, and they are
--      idempotent.
-- ============================================================================

