CREATE OR REPLACE FUNCTION public.search_all_columns(search_value text)
 RETURNS TABLE(found_table text, found_column text, row_id text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
    rec record;
    match_count integer;
    id_column text;
begin
    -- Loop through all tables and columns in the public schema
    for rec in 
        select c.table_name, c.column_name 
        from information_schema.columns c
        join information_schema.tables t on t.table_name = c.table_name
        where c.table_schema = 'public' 
          and t.table_type = 'BASE TABLE'
          and c.data_type in ('text', 'character varying', 'integer', 'uuid', 'bigint')
    loop
        -- Fixed ambiguity by using explicit table prefixes
        select cols.column_name into id_column
        from information_schema.columns cols
        where cols.table_schema = 'public' 
          and cols.table_name = rec.table_name 
          and cols.column_name = 'id';

        if id_column is null then
            id_column := 'NULL';
        else
            id_column := quote_ident(id_column) :: text;
        end if;

        -- Execute dynamic SQL to see if the value exists
        execute format('select count(*) from %I where %I::text = %L', 
            rec.table_name, rec.column_name, search_value) into match_count;

        -- If a match is found, return the details
        if match_count > 0 then
            return query execute format(
                'select %L::text, %L::text, %s::text from %I where %I::text = %L limit 1',
                rec.table_name, rec.column_name, id_column, rec.table_name, rec.column_name, search_value
            );
        end if;
    end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.search_all_tables(search_val text)
 RETURNS TABLE(table_name text, column_name text, row_id text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    r RECORD;
BEGIN
    FOR r IN 
        SELECT t.table_name, c.column_name
        FROM information_schema.tables t
        JOIN information_schema.columns c ON c.table_name = t.table_name
        WHERE t.table_schema = 'public' 
          AND t.table_type = 'BASE TABLE'
          -- Focus on text-based columns to avoid type errors
          AND c.data_type IN ('character varying', 'text')
    LOOP
        RETURN QUERY EXECUTE format(
            'SELECT %L::text, %L::text, id::text FROM %I WHERE %I::text ILIKE %L',
            r.table_name, r.column_name, r.table_name, r.column_name, '%' || search_val || '%'
        );
    END LOOP;
END;
$function$
;


